class AsyncCache<T> {
  AsyncCache(this._fetch);

  final Future<T> Function(String key) _fetch;
  final _inFlight = <String, Future<T>>{};

  Future<T> get(String key) {
    // Hay uno en vuelo o ya resuelto: reutilízalo.
    final existing = _inFlight[key];
    if (existing != null) return existing;

    // Se inserta SÍNCRONAMENTE, antes de cualquier await.
    // Por eso las llamadas concurrentes encuentran este mismo future.
    final future = _fetch(key);
    _inFlight[key] = future;

    // Si falla, se retira para no envenenar la clave.
    future.catchError((Object error) {
      _inFlight.remove(key);
      throw error;   // se relanza para que el llamador lo reciba
    });

    return future;
  }

  void invalidate(String key) => _inFlight.remove(key);
  void clear() => _inFlight.clear();
}
```

```dart
Future<T> retry<T>(
  Future<T> Function() operation, {
  int maxAttempts = 5,
  Duration initialDelay = const Duration(milliseconds: 200),
  Duration maxDelay = const Duration(seconds: 30),
  bool Function(Object error)? retryIf,
  bool Function()? isCancelled,
}) async {
  final random = Random();
  var attempt = 0;

  while (true) {
    attempt++;
    try {
      return await operation();
    } catch (error) {
      final noMoreAttempts = attempt >= maxAttempts;
      final permanent = retryIf != null && !retryIf(error);
      final cancelled = isCancelled?.call() ?? false;

      if (noMoreAttempts || permanent || cancelled) rethrow;

      // Exponencial, acotado, y con jitter para romper la sincronización
      // entre clientes tras una caída del servidor.
      final exponential = initialDelay.inMilliseconds * pow(2, attempt - 1);
      final capped = min(exponential.toInt(), maxDelay.inMilliseconds);
      final jittered = random.nextInt(capped + 1);

      await Future<void>.delayed(Duration(milliseconds: jittered));
    }
  }
}

// Uso: solo se reintenta lo transitorio.
final user = await retry(
  () => api.fetchUser(id),
  retryIf: (e) => e is SocketException || (e is HttpException && e.code >= 500),
);
```

```dart
Future<({int cumplen, double media})> procesar(String ruta) async {
  final file = File(ruta);

  var cumplen = 0;
  var suma = 0.0;
  var contados = 0;
  var primera = true;

  final lineas = file
      .openRead()
      .transform(utf8.decoder)      // gestiona caracteres partidos entre trozos
      .transform(const LineSplitter()); // gestiona líneas partidas entre trozos

  // await for aplica contrapresión: no se lee más hasta procesar esta línea.
  await for (final linea in lineas) {
    if (primera) { primera = false; continue; }  // cabecera
    if (linea.isEmpty) continue;

    final campos = linea.split(',');
    final valor = double.tryParse(campos[2]);
    if (valor == null) continue;   // fila corrupta: no abortar por una línea

    if (campos[1] == 'activo') cumplen++;
    suma += valor;
    contados++;
  }

  return (cumplen: cumplen, media: contados == 0 ? 0 : suma / contados);
}
```

