class User {
  const User({
    required this.id,
    required this.name,
    this.bio = '',
    this.tags = const [],
  });

  factory User.fromJson(Map<String, dynamic> json) {
    // Esencial: si falta o es inválido, fallamos aquí y no más adelante.
    final id = _string(json['id']);
    if (id == null || id.isEmpty) {
      throw FormatException('User sin id válido', json);
    }

    return User(
      id: id,
      name: _string(json['name']) ?? 'Sin nombre',
      bio: _string(json['bio']) ?? '',
      tags: _stringList(json['tags']),
    );
  }

  final String id;
  final String name;
  final String bio;
  final List<String> tags;

  /// Acepta String y también números, que algunas APIs envían sin comillas.
  static String? _string(Object? value) => switch (value) {
    final String s => s,
    final num n => n.toString(),
    _ => null,
  };

  /// Tolera que el campo llegue como elemento suelto en vez de como lista.
  static List<String> _stringList(Object? value) => switch (value) {
    final List<dynamic> list =>
      list.map(_string).whereType<String>().toList(growable: false),
    final String s => [s],
    _ => const [],
  };
}
