```dart
typedef TaskResult<T> = ({T? value, Object? error});

Future<List<TaskResult<T>>> runWithConcurrency<T>(
  List<Future<T> Function()> tasks, {
  int concurrency = 6,
}) async {
  final results = List<TaskResult<T>?>.filled(tasks.length, null);
  var nextIndex = 0;

  Future<void> worker() async {
    while (true) {
      // Atómico: no hay await entre la lectura y el incremento,
      // así que ningún otro trabajador puede colarse aquí.
      final index = nextIndex++;
      if (index >= tasks.length) return;

      try {
        results[index] = (value: await tasks[index](), error: null);
      } catch (error) {
        // Un fallo no aborta el resto.
        results[index] = (value: null, error: error);
      }
    }
  }

  final workers = List.generate(
    min(concurrency, tasks.length),
    (_) => worker(),
  );
  await Future.wait(workers);

  return results.cast<TaskResult<T>>();
}
```

```dart
class IsolateWorker {
  IsolateWorker._(this._isolate, this._sendPort, this._receivePort);

  final Isolate _isolate;
  final SendPort _sendPort;
  final ReceivePort _receivePort;
  final _pending = <int, Completer<Object?>>{};
  var _nextId = 0;
  var _closed = false;

  static Future<IsolateWorker> spawn() async {
    final receivePort = ReceivePort();
    final isolate = await Isolate.spawn(_entryPoint, receivePort.sendPort);

    final events = receivePort.asBroadcastStream();
    // Handshake: el primer mensaje del hijo es su SendPort.
    final sendPort = await events.first as SendPort;

    final worker = IsolateWorker._(isolate, sendPort, receivePort);
    events.listen(worker._onMessage);
    return worker;
  }

  Future<Object?> request(Object? payload) {
    if (_closed) throw StateError('Worker cerrado');
    final id = _nextId++;
    final completer = Completer<Object?>();
    _pending[id] = completer;          // así sabremos a quién responder
    _sendPort.send((id: id, payload: payload));
    return completer.future;
  }

  void _onMessage(dynamic message) {
    final (:int id, :Object? result, :Object? error) = message as dynamic;
    final completer = _pending.remove(id);
    if (completer == null) return;     // respuesta huérfana: ignorar
    error != null
        ? completer.completeError(error)
        : completer.complete(result);
  }

  Future<void> close() async {
    _closed = true;
    // Nadie debe quedarse esperando para siempre.
    for (final completer in _pending.values) {
      completer.completeError(StateError('Worker cerrado'));
    }
    _pending.clear();
    _receivePort.close();
    _isolate.kill(priority: Isolate.immediate);
  }

  static void _entryPoint(SendPort toParent) {
    final fromParent = ReceivePort();
    toParent.send(fromParent.sendPort);   // completa el handshake

    fromParent.listen((dynamic message) {
      final (:int id, :Object? payload) = message as dynamic;
      try {
        toParent.send((id: id, result: _process(payload), error: null));
      } catch (error) {
        // Se envía como mensaje: así se completa el completer correcto.
        toParent.send((id: id, result: null, error: error.toString()));
      }
    });
  }

  static Object? _process(Object? payload) => payload; // el trabajo real
}
```

